  ui_story_5087_50870100_10_dialog_content = "\"หนึ่งต้นสร้างใบ อีกต้นผลิดอกไม้ พวกเขาดื่มน้ำค้างยามเช้า รากของพวกเขาผูกพันกันตลอดไป\"",
