  ui_story_5087_50870100_12_dialog_content = "แต่น่าเสียดายที่ทุกเรื่องราวจำเป็นต้องมีการหักมุม",
  ui_story_5087_50870100_13_dialog_content = "\"ภายใต้หิมะสีเทาที่ตกหนัก ดอกลิลลี่ที่สะอาดเนียนก็ถูกกลบซ่อนไปอย่างรวดเร็ว\"",
  ui_story_5087_50870100_14_dialog_content = "\"ถูกทิ้งเอาไว้คนเดียวในโลกนี้ นาร์ซิสซัสสีขาวร้องไห้อย่างเงียบ ๆ\"",
