  ui_story_5087_50870600_1_dialog_content = "<color=#e8d9bb>ค่ำคืนลงมา และพายุหิมะที่ร้องไห้ปกคลุมท้องฟ้าด้วยหิมะ แม้แต่เงาของเปลวไฟภายในเตาไฟดูเหมือนจะแสงสว่างด้วยความไม่สบายใจ</color>",
  ui_story_5087_50870600_2_dialog_content = "(สงสัยจังว่าพ่อแม่ทนอยู่กับพายุแบบนี้ได้ยังไงนะ... แน่นอนพวกเขาคงไม่อยู่นอกบ้านในคืนแบบนี้หรอกนะ, ฉันเดา?)",
  ui_story_5087_50870600_3_dialog_content = "ฉันทำการรายงานทุกอย่างให้สมเด็จพระราชินีเรียบร้อยแล้วนะ นิคินิส! เธอดูพอใจกับผลงานของเรามากเลย!",
  ui_story_5087_50870600_4_dialog_content = "นั่นสวยงามจริงๆ ในที่สุดเราก็สามารถกลับบ้านและใช้เวลากับพ่อแม่ได้แล้ว",
  ui_story_5087_50870600_5_dialog_content = "โอ๊ะ... จริงด้วย...",
  ui_story_5087_50870600_6_dialog_content = "เนโปลิส! นิคินิส! โอ้ ขอบคุณพระเจ้าที่คุณยังไม่ได้ออกเดินทางอีก!",
  ui_story_5087_50870600_7_dialog_content = "มีจดหมายจากพ่อแม่คุณเข้ามาเพิ่งนี้ พวกเขาบอกว่าพวกเขายังคงดำเนินการตามคำสั่งของสมเด็จพระราชินี ดังนั้นพวกเขาจะไม่สามารถกลับมาได้อีกสองสามวัน",
  ui_story_5087_50870600_8_dialog_content = "ในพายุแบบนี้ คุณไม่ควรกลับไปตอนนี้ดีที่สุด คุณไม่ต้องการติดอยู่ในหิมะใช่ไหม?",
  ui_story_5087_50870600_9_dialog_content = "ต-แต่...",
  ui_story_5087_50870600_10_dialog_content = "เขามีเหตุผลนะ นิคินิส การพยายามนำทางในพายุหิมะตอนกลางคืนนั้นอันตรายเกินไป",
  ui_story_5087_50870600_11_dialog_content = "อีกทั้งพ่อแม่ของเราก็ไม่อยู่บ้านตอนนี้ มาพักคืนที่ไหนสักแห่งใกล้ๆ กันเถอะ โอเคไหม?",
  ui_story_5087_50870600_12_dialog_content = "งั้นเหรอ...",
  ui_story_5087_50870600_13_dialog_content = "(ฉันไม่คิดว่าเคยเห็นพ่อแม่ที่พระราชวังฤดูหนาวมาก่อน... หรือนี่จะเป็นผลข้างเคียงจากโรคที่ฉันเป็นหรือไม่?)",
  ui_story_5087_50870600_14_dialog_content = "(ถ้าพวกเขาทำงานให้กับสมเด็จพระราชินี แน่นอน Nepolis และฉันคงจะเห็นพวกเขาที่พระราชวังแล้ว ใช่ไหม?)",
  ui_story_5087_50870600_15_dialog_content = "(แต่พวกเขาจริง ๆ แล้วทำตามคำสั่งของสมเด็จพระราชินีหรือไม่? เมื่อไหร่พวกเขาเริ่มทำเช่นนั้น? ทำไมฉันจำไม่ได้เรื่องนี้เลย?)",
  ui_story_5087_50870600_16_dialog_content = "(สิ่งเดียวที่ฉันจำได้ชัดเจนคือพวกเขานำเราไปที่พระราชวังเหมันต์เพื่อรักษา)",
  ui_story_5087_50870600_17_dialog_content = "(หลังจากนั้น ฉันก็จำหน้าของพวกเขาได้ยากแท้...)",
  ui_story_5087_50870600_18_dialog_content = "(หรือว่าโรคของฉันได้กระทบต่อความทรงจำของฉันในทางหนึ่งหรือเปล่า?)",
  ui_story_5087_50870600_19_dialog_content = "(แม้ว่าฉันจะไม่รู้จักเรื่องนี้เลย แต่เนโปลิสและทูตนั้นกล่าวถึงมันเหมือนว่ามันเป็นเรื่องปกติ มันเหมือนว่า...)",
  ui_story_5087_50870600_20_dialog_content = "(โลกนี้ถูกปกคลุมด้วยชั้นของภาพลวงตา)",
  ui_story_5087_50870600_21_dialog_content = "(ไม่... ฉันต้องเป็นคนคิดไปเอง น้องสาวของฉันเป็นความจริง ไม่มีที่สงสัยเลย)",
  ui_story_5087_50870600_22_dialog_content = "... อ๊ะ!",
  ui_story_5087_50870600_23_dialog_content = "มันคืออะไร, เนโปลิส?",
  ui_story_5087_50870600_24_dialog_content = "ผมฉัน! มันติดอยู่กับกิ่งไม้หนึ่ง! ช่วยฉันด้วย นิคินิส!",
  ui_story_5087_50870600_25_dialog_content = "ตรงๆ นี่... นี่คุณทำยังไงถึงได้ติดอยู่บนกิ่งเนี่ย? หยุดดิ้นได้แล้วก่อนที่คุณจะทำร้ายตัวเอง!",
  ui_story_5087_50870600_26_dialog_content = "เพราะว่าฉันเห็นกระรอกน้อยน่ารักเมื่อกี้ ฉันเดินไปใกล้เพื่อดูให้ชัดขึ้น แต่แล้ว...",
  ui_story_5087_50870600_27_dialog_content = "คุณทำสิ่งที่น่าทึ่งได้เมื่อฉันไม่ได้สนใจนะ คุณรู้ไหม?",
  ui_story_5087_50870600_28_dialog_content = "คุณนิคินิส คุณก็ควรจะพูดเถอะ คุณได้ค้นพบพลังและความรู้สึกทุกประเภทในช่วงนี้ ทั้งหมดนี้โดยที่ฉันไม่รู้เลย...",
  ui_story_5087_50870600_29_dialog_content = "เราเคยเป็นหนึ่งเดียวกัน จำได้ไหม? หัวใจและจิตใจของเราเชื่อมต่อกัน และเราแบ่งปันทุกอย่างตั้งแต่ลักษณะทางภายนอก ความสามารถ ถึงความชอบและความไม่ชอบของเรา",
  ui_story_5087_50870600_30_dialog_content = "การมองเธอที่กำลังเปลี่ยนไปเป็นคนอื่น ๆ ทำให้ฉันรู้สึกเหงาบางครั้ง...",
  ui_story_5087_50870600_31_dialog_content = "ดูช่อดอกไม้ที่คุณได้รับนั้น—ดอกนาร์ซิสซัสถูกมัดรวมกับดอกกุหลาบสีเหลืองและดอกลืมไม่ลืม แต่ไม่มีดอกลิลลี่เลย...",
  ui_story_5087_50870600_32_dialog_content = "เนโปลิส... คุณกำลังพูดอะไรกันอยู่เนี่ย? ไม่มีคู่พี่น้องใดในโลกนี้ที่คล้ายกันมากกว่าเราสองคน! เมื่อไหร่เรากลายเป็น \"ต่างกัน\" ในความคิดของคุณ?",
  ui_story_5087_50870600_33_dialog_content = "ฉันสัญญาว่าจะไม่เข้าใกล้กระจกนั่นอีกเลย ดังนั้นโปรดอย่าห่วงใยฉันนะ โอเคมั้ย?",
  ui_story_5087_50870600_34_dialog_content = "... นี่แหละ! ผมของคุณไม่พันกันแล้วนะ ออกมาจากใต้ต้นไม้นั้นเถอะ",
  ui_story_5087_50870600_35_dialog_content = "อิสระที่หอมหวาน, อิสระที่หอมหวาน!",
  ui_story_5087_50870600_36_dialog_content = "... ขอบคุณนะ นิคินิส ถ้าไม่มีคุณ ฉันไม่รู้จะทำอะไรดี",
  ui_story_5087_50870600_37_dialog_content = "ดังนั้น หยุดพูดเรื่องที่ว่า \"ฉันไม่มีประโยชน์ต่อน้องสาวฉัน...\"",
  ui_story_5087_50870600_38_dialog_content = "การมีคุณอยู่เคียงข้างเป็นพรที่ยิ่งใหญ่ที่สุดที่ฉันอาจขอได้",
  ui_story_5087_50870600_39_dialog_content = "(เนโปลิสเป็นจริง และฉันก็เช่นกัน ไม่มีคำถามเกี่ยวกับสิ่งนี้เลย)",
  ui_story_5087_50870600_40_dialog_content = "(นั่นเป็นเหตุผลที่... ฉันต้องทำลายกระจกลึกลับนี้)",
  ui_story_5087_50870600_41_dialog_content = "นิคินิส... นั่นคุณเหรอ?",
  ui_story_5087_50870600_42_dialog_content = "(... เขากลับมาอีกแล้ว!)",
  ui_story_5087_50870600_43_dialog_content = "ได้โปรดอย่าคุยกับฉันอีกต่อไป ฉันไม่อยากให้พี่สาวของฉันต้องทนทุกข์แบบนี้อีก!",
  ui_story_5087_50870600_44_dialog_content = "ฟังฉันดี ๆ นะ นิคินิส! คุณต้องไป... และหา... แค่นั้นเท่านั้น...",
  ui_story_5087_50870600_45_dialog_content = "ไปที่ไหน? ฉันควรจะหาอะไร?",
  ui_story_5087_50870600_46_dialog_content = "คุณคือใครและทำไมคุณถึงคุยกับฉันผ่านกระจกเรื่อยๆ?",
  ui_story_5087_50870600_47_dialog_content = "ฉัน... คุณอยู่ใน... เพียงโดย... คุณจึงสามารถ...",
  ui_story_5087_50870600_48_dialog_content = "...ฉันไม่เข้าใจอะไรที่คุณกำลังพูดเลย  เสียงของคุณหายไปอย่างรวดเร็วในช่วงเวลาที่แย่ที่สุด!",
  ui_story_5087_50870600_49_dialog_content = "มันคือสิ่งนั้น! มันยังคงรบกวนเรา! แม้หลังจากที่เราทำลาย... มันก็ไม่เคยหยุด มันยังคงขวาง... อ๊ะ!",
  ui_story_5087_50870600_50_dialog_content = "\"พัง\"? เธอกำลังพูดถึงกระจกเงานอร์ธแลนด์เหรอ? เธอรู้ว่าใครทำมั้ย? รอสักครู่, เธอทำไมถึงรู้ว่ากระจกพังล่ะ?",
  ui_story_5087_50870600_51_dialog_content = "อาจจะเป็นไปได้ไหม... ว่าคุณคือผู้ที่ขโมยกระจกเงาของนอร์ธแลนด์?",
  ui_story_5087_50870600_52_dialog_content = "<color=#e8d9bb>ก่อนที่คนในกระจกจะตอบได้ พายุหิมะก็กระแทกเข้าหากระท่อมอย่างรุนแรงขึ้น ทำให้หน้าต่างสั่นไหวในกรอบของมัน</color>",
  ui_story_5087_50870600_53_dialog_content = "<color=#e8d9bb>นิคินิสก้มหัวลงอีกครั้ง กระจกที่อยู่ในมือเธอสะท้อนแต่เพลิงที่ลุกโชนจากเตาไฟและหิมะที่หวนหันอยู่ข้างนอกเท่านั้น</color>",
  ui_story_5087_50870700_1_dialog_content = "<color=#e8d9bb>หิมะยังคงตกลงมาในขณะที่เมฆที่มืดมิดและสงบนิ่งครอบคลุมดินแดนทางเหนือ ภาพลักษณ์ที่มืดมิดและสงบนี้สะท้อนถึงอารมณ์ของนิคินิสโดยตรง</color>",
  ui_story_5087_50870700_2_dialog_content = "<color=#e8d9bb>บ้านที่ไม่สามารถเข้าถึงได้, ปริศนาที่ไม่สามารถแก้ไขได้, และความทรงจำที่ไม่แน่นอน... ทั้งหมดนี้ทำให้หัวใจของเธอรู้สึกหนักหน่วง</color>",
  ui_story_5087_50870700_3_dialog_content = "<color=#e8d9bb>ความหวังเพียงหยิบหย่อยของเธอคือกระจกเงาที่อยู่ในมือ เธอเกือบจะทำลายมัน</color>",
  ui_story_5087_50870700_4_dialog_content = "(ดูเหมือนว่าคนในกระจกจะไม่กลับมาเร็ว ๆ นี้...)",
  ui_story_5087_50870700_5_dialog_content = "(มีคนจริง ๆ มายุ่งกับการสื่อสารของเราหรือไม่? อาจจะเป็นคนที่ทำลายกระจกในตอนแรกเลย)",
  ui_story_5087_50870700_6_dialog_content = "(คนในกระจกนั่นต้องการให้ฉันทำอะไร... แต่ทำไม? พวกเขากำลังต่อสู้กับผู้ที่ทำลายกระจกหรือ? คำถามมันไม่มีที่สิ้นสุด...)",
  ui_story_5087_50870700_7_dialog_content = "นิคินิส! เรามีปัญหา!",
  ui_story_5087_50870700_8_dialog_content = "อะ-อะไรนะ?",
  ui_story_5087_50870700_9_dialog_content = "หืม? ทำไมดูเหมือนว่าคุณสับสนขนาดนั้น? อย่าบอกฉันว่าคุณได้รับจดหมายรักหรืออะไรทำนองนั้น.",
  ui_story_5087_50870700_10_dialog_content = "ไม่ใช่เลย! ถึงมีฉันก็ไม่ได้ปิดบังจากคุณ—",
  ui_story_5087_50870700_11_dialog_content = "ฉันจะไม่มีวันปล่อยให้คุณกังวลเรื่องแบบนั้น, Nepolis. เชื่อฉันนะ.",
  ui_story_5087_50870700_12_dialog_content = "... คุณไม่จำเป็นต้องปกป้องตัวเองอย่างนี้นะ คุณรู้ไหม? จดหมายรักของคุณก็เป็นเรื่องของคุณเองหลังจากนี้",
  ui_story_5087_50870700_13_dialog_content = "ไม่มีจดหมายรัก!",
  ui_story_5087_50870700_14_dialog_content = "โอ-โอเค ฉันเชื่อคุณแล้ว! ตอนนี้ก็ฟังฉันสิ เพราะเกิดเรื่องใหญ่ขึ้นมาแล้ว—",
  ui_story_5087_50870700_15_dialog_content = "สมเด็จพระราชินีเพิ่งประกาศลงรูปของโจรกระจก!",
  ui_story_5087_50870700_16_dialog_content = "อะไร ที่ไหน",
  ui_story_5087_50870700_17_dialog_content = "โอ้? ฉันไม่คิดเลยว่าคุณจะเป็นห่วงมันขนาดนี้ มากับฉันสิ",
  ui_story_5087_50870700_18_dialog_content = "ควีนเบธเลเฮมได้เปิดเผยตัวตนของโจรและได้โพสต์ภาพเหมือนของพวกเขาให้ทั้งหมดเห็น",
  ui_story_5087_50870700_19_dialog_content = "เริ่มต้นจากวันนี้ เขตแดนของนอร์ธแลนด์จะถูกปิดกั้น และกำลังทหารจะมุ่งเน้นไปที่การจับกุมโจร ทุกคนที่อาศัยอยู่ในนอร์ธแลนด์จะถูกขอให้รายงานกิจกรรมที่น่าสงสัยทันที!",
  ui_story_5087_50870700_20_dialog_content = "พวกเขากำลังปิดแนวชายแดน? ฝ่าบาทนายามไม่ค่อยเคลื่อนย้ายอาณาจักรอย่างนี้...",
  ui_story_5087_50870700_21_dialog_content = "คุณไม่ได้เห็นเหตุการณ์ที่เกิดขึ้นเช้านี้หรือเปล่า? พระราชวังเหมันต์ส่งกองทัพออกไล่ล่าโจรนี้เกือบทั้งหมดเลย!",
  ui_story_5087_50870700_22_dialog_content = "มีเหตุผลสำหรับฉัน สุดท้ายแล้วไม่ใช่ทุกคนที่สามารถแอบเข้าไปในคลังสมบัติของวังหิมะได้",
  ui_story_5087_50870700_23_dialog_content = "แม้แต่เพียงชิ้นเดียวของเรลิกนั้นก็มีพลังพอที่จะทำลายหมู่บ้านได้ถึงร้อยแห่ง สมเด็จพระราชินีทำทุกอย่างนี้เพื่อเราเท่านั้น",
  ui_story_5087_50870700_24_dialog_content = "ลองมาดูภาพเหล่านี้—เหมือนว่าโจรจะเป็นสาวน้อย! เด็กจะสามารถบุกเข้าไปในพระราชวังเหมันต์ได้อย่างไรนะ?",
  ui_story_5087_50870700_25_dialog_content = "(เด็กผู้หญิงตัวน้อย? อย่าบอกฉันว่า...)",
  ui_story_5087_50870700_26_dialog_content = "ขอโทษนะ! ผ่านไปค่ะ—",
  ui_story_5087_50870700_27_dialog_content = "(ฉันรู้แล้ว... มันคือเธอ!)",
  ui_story_5087_50870700_28_dialog_content = "คุณก็ตกใจเหมือนกันใช่ไหม นิคินิส? ดูเหมือนว่าโจรที่ถูกตามหามากที่สุดของนอร์ธแลนด์ก็แค่สาวน้อยที่น่ารัก...",
  ui_story_5087_50870700_29_dialog_content = "ฉ-ฉันต้องไปแล้วนะ, เนโปลิส!",
  ui_story_5087_50870700_30_dialog_content = "หือ? รอสักครู่ นิคินิส สมเด็จพระราชินีมอบภารกิจอีกหนึ่งให้เรา—",
  ui_story_5087_50870700_31_dialog_content = "เฮ้! คุณอยู่ในนั้นรึเปล่า? กรุณาพูดอะไรสักหน่อยสิ!",
  ui_story_5087_50870700_32_dialog_content = "(ไม่มีการตอบสนอง... ฉันทำอย่างไรให้คนในกระจกปรากฏขึ้นครั้งล่าสุด? ถูกต้อง! มันคือเมื่อฉันคิดถึงการใช้ Luminatics เพื่อทำลายมัน!)",
  ui_story_5087_50870700_33_dialog_content = "(ฉันจะลองผสมกระจกด้วย Lumina ก่อน...)",
  ui_story_5087_50870700_34_dialog_content = "นิคินิส!",
  ui_story_5087_50870700_35_dialog_content = "คุณมาแล้ว! บอกฉันสิ, คุณทำงานร่วมกับสาวน้อยที่ชื่อชาญ่าหรือ?",
  ui_story_5087_50870700_36_dialog_content = "คุณสองคนนี่แหละที่ขโมยกระจกของ Northland ใช่มั้ย?",
  ui_story_5087_50870700_37_dialog_content = "... นั่นแหละ ชาญ่าจริงๆแล้ว... เพราะเธอ... และเข้าไป... ด้วยตัวเอง...",
  ui_story_5087_50870700_38_dialog_content = "กระจกนอร์ธแลนด์คือทางผ่านที่เราเตรียมไว้ให้คุณ... แต่มันถูกทำลายโดย...",
  ui_story_5087_50870700_39_dialog_content = "ต้องมีการซ่อมแซมก่อน... นั่นเป็นเหตุผลว่าทำไมเราถึงต้องการความช่วยเหลือจากคุณ",
  ui_story_5087_50870700_40_dialog_content = "เราส่งชาญ่าไปส่งกระจกนี้ให้คุณ เพื่อที่เราจะสื่อสารกันได้",
  ui_story_5087_50870700_41_dialog_content = "พูดอะไรน่ะ?! บอกผมมาว่าคุณกำลังวางแผนอะไรอยู่!",
  ui_story_5087_50870700_42_dialog_content = "ฉันไม่สามารถตอบคุณได้ในตอนนี้ ทุกครั้งที่ฉันพยายามจะบอกคุณสักอย่าง... ถูกบล็อก.",
  ui_story_5087_50870700_43_dialog_content = "ค้นหาชาญ่า และเธอจะบอกคุณทุกอย่าง... ตอนนี้เธอคือคนเดียวที่สามารถช่วยคุณได้!",
  ui_story_5087_50870700_44_dialog_content = "<color=#e8d9bb>บุคคลในกระจกหายไปอย่างกะทันหันพร้อมกับแสงแฟลช</color>",
  ui_story_5087_50870700_45_dialog_content = "(การตัดสินใจของพระราชินีไม่ได้ผิดพลาดเลย... คนที่ขโมยกระจกเงานอร์ธแลนด์คือชาญ่า)",
  ui_story_5087_50870700_46_dialog_content = "(ไม่เพียงแค่นั้น เธอและคนในกระจกกำลังวางแผนอะไรสักอย่างร่วมกัน)",
  ui_story_5087_50870700_47_dialog_content = "(แต่ทำไม? ฉันไม่รับรู้ถึงความอาฆาตมาจากชาญ่าหรือกระจกนี้เลย...)",
  ui_story_5087_50870700_48_dialog_content = "...",
  ui_story_5087_50870700_49_dialog_content = "(ฉันจะเก็บกระจกไว้ในที่ที่ไม่มองเห็นก่อน เนโพลิสจะกลับมาในไม่ช้านี้แน่นอน)",
  ui_story_5087_50870700_50_dialog_content = "(ฉันไม่น่าเชื่อว่าฉันกำลังเก็บความลับที่ใหญ่มากจากเธอ... ด้วยการไว้วางใจในกระจก ฉันจะทำให้ระยะห่างระหว่างเรามากขึ้นหรือเปล่า)",
  ui_story_5087_50870700_51_dialog_content = "นิคินิส! เธอวิ่งหนีไปคนเดียวแบบนั้นได้ยังไง?",
  ui_story_5087_50870700_52_dialog_content = "...ฉันขอโทษ",
  ui_story_5087_50870700_53_dialog_content = "สมเด็จพระราชินีสั่งให้เราจับโจรที่ขโมยกระจก! เราไม่มีเวลาเสียเลย ดังนั้นรีบเอาเสื้อคลุมและรองเท้าของคุณ—",
  ui_story_5087_50870700_54_dialog_content = "โอ้! ขอโทษนะ ฉันจะไปทันที! ขอบคุณที่แจ้งให้ฉันรู้... ขอโทษที่รีบหนีไปเมื่อกี้นะ",
  ui_story_5087_50870700_55_dialog_content = "... ทำไมคุณถึงขอโทษมากขนาดนี้? เราเป็นพี่น้องกัน จำได้ไหม?",
  ui_story_5087_50870700_56_dialog_content = "คุณคือคนที่สำคัญที่สุดในชีวิตฉัน ไม่ว่าจะเกิดอะไรขึ้น สิ่งนั้นจะไม่เปลี่ยนแปลงเลย",
  ui_story_5087_50870800_1_dialog_content = "ฉันจะไปดูที่นั่น นีโปลิส",
  ui_story_5087_50870800_2_dialog_content = "แล้วฉันจะดูที่นี่ รักษาความระมัดระวังของคุณ",
  ui_story_5087_50870800_3_dialog_content = "ฉันจะไม่เป็นไรหรอก นอกจากนี้ ฉันยังรู้ว่าคุณจะมาช่วยฉันทันทีที่คุณรู้สึกว่าฉันกำลังประสบปัญหา",
  ui_story_5087_50870800_4_dialog_content = "เป็นพี่น้องฝาแฝด เราเชื่อมต่อกันทั้งจิตใจและวิญญาณ จำได้ไหม?",
  ui_story_5087_50870800_5_dialog_content = "...",
  ui_story_5087_50870800_6_dialog_content = "(ที่นี่ควรจะปลอดภัยพอแล้ว.)",
  ui_story_5087_50870800_7_dialog_content = "เฮ้ เธออยู่ไหม",
  ui_story_5087_50870800_8_dialog_content = "มันคืออะไร นิคินิส? คุณหาชาญ่าเจอหรือยัง?",
  ui_story_5087_50870800_9_dialog_content = "ยังไม่เจอเลย ฉันกับพี่สาวกำลังค้นหาเธออยู่ในขณะนี้ รวมถึงทั้งราชวงศ์",
  ui_story_5087_50870800_10_dialog_content = "ฉันไม่สามารถจำเวลาได้ที่ทั้งนอร์ธแลนด์ถูกเรียกมารวมตัวเพื่อล่าโจรคนเดียว มีบางอย่างเกี่ยวกับโลกนี้ที่ดูไม่ถูกต้องหลังจากทั้งหมด...",
  ui_story_5087_50870800_11_dialog_content = "นั่นเพราะว่าคุณ... แต่ไม่ต้องห่วงเรื่องชาญ่านะ ทั้งนี้เพราะว่าเธอเป็น... คนธรรมดาไม่ควรจะเป็นอันตรายต่อเธอหรอก",
  ui_story_5087_50870800_12_dialog_content = "ฟังฉันด้วยนะ กระจก! ฉัน...",
  ui_story_5087_50870800_13_dialog_content = "ฉันอยากจะบอกพี่สาวของฉันทุกอย่างที่ฉันรู้เกี่ยวกับคุณและชาญ่า...",
  ui_story_5087_50870800_14_dialog_content = "ฮะ? ฉัน... ฉันไม่แน่ใจว่านั่นเป็นความคิดที่ดี...",
  ui_story_5087_50870800_15_dialog_content = "พี่สาวฉันและฉันเราเป็นหนึ่งเดียวกัน",
  ui_story_5087_50870800_16_dialog_content = "ห๊ะ",
  ui_story_5087_50870800_17_dialog_content = "ตั้งแต่เรามาสู่โลกนี้ เราได้อยู่ด้วยกันตลอดเวลา ดังดอกไม้สองดวงที่ถูกปลูกข้างกัน เราเติบโตและบานออกมาในทางเดียวกันเลย",
  ui_story_5087_50870800_18_dialog_content = "ฉันอธิบายไม่ได้ว่าทำไม แต่ฉันรู้ว่าคุณและชาญ่าไม่ใช่คนเลว อาจจะเป็นสัญชาตญาณของฉัน...",
  ui_story_5087_50870800_19_dialog_content = "และถ้าเป็นอย่างนั้น พี่สาวของฉันจะมีสัมผัสใจที่เหมือนกับฉัน ไม่ว่าคุณกำลังวางแผนอะไร พี่สาวของฉันจะไม่ขัดขวางคุณ",
  ui_story_5087_50870800_20_dialog_content = "ในความเป็นจริง, เธอจะช่วยคุณ",
  ui_story_5087_50870800_21_dialog_content = "... มั่นใจขนาดนั้นเลยรึ?",
  ui_story_5087_50870800_22_dialog_content = "บวก. เพราะฉันกำลังคิดเรื่องเดียวกันอยู่แล้ว",
  ui_story_5087_50870800_23_dialog_content = "ฉันเพียงแค่ต้องมองลึกลงไปในหัวใจของตัวเอง เพื่อทราบว่าพี่สาวของฉันจะเลือกอย่างไร",
  ui_story_5087_50870800_24_dialog_content = "...ฉันเข้าใจ",
  ui_story_5087_50870800_25_dialog_content = "ฉันมีคำขออีกหนึ่งเรื่อง ราชินีเบธเลเฮมคือผู้ที่สั่งจับชาญ่า ซึ่งหมายความว่าเธอต้องรู้บางอย่าง",
  ui_story_5087_50870800_26_dialog_content = "ถ้าฉันบอกเธอเรื่องอื่น ๆ ด้วย เธอจะโอเคมั้ยนะ—",
  ui_story_5087_50870800_27_dialog_content = "ไม่ได้อย่างแน่นอน!",
  ui_story_5087_50870800_28_dialog_content = "?",
  ui_story_5087_50870800_29_dialog_content = "\"ราชินีเบธเลเฮม\" นั่น... เธอไม่ได้... ดังนั้นคุณไม่สามารถ...",
  ui_story_5087_50870800_30_dialog_content = "ฉันไม่ได้ยินสิ่งที่คุณกำลังพูด ฉันคิดว่าการรบกวนสัญญาณกำลังแย่ลง",
  ui_story_5087_50870800_31_dialog_content = "อืม! ฉันจะบอกคุณยังไงดี... อย่าเชื่อ... ของปลอม!",
  ui_story_5087_50870800_32_dialog_content = "อะไรที่เป็นของปลอม? จดหมายจากทูตนั้นหรือ? เรื่องราวเกี่ยวกับพ่อแม่ของฉันหรือ? หรือความทรงจำของฉัน?",
  ui_story_5087_50870800_33_dialog_content = "หรือว่าจะเป็น... สมเด็จพระราชินี?",
  ui_story_5087_50870800_34_dialog_content = "ครับ",
  ui_story_5087_50870800_35_dialog_content = "สมเด็จเป็นปลอม?",
  ui_story_5087_50870800_36_dialog_content = "ใช่! มันเป็นความจริง! เธอ... เป้าหมายของเธอคือ...",
  ui_story_5087_50870800_37_dialog_content = "... หยุดอยู่ตรงนั้นเลย!",
  ui_story_5087_50870800_38_dialog_content = "?",
  ui_story_5087_50870800_39_dialog_content = "อั่ก!",
  ui_story_5087_50870800_40_dialog_content = "ในที่สุดก็จับได้สักที! ลองดูว่าคุณจะวิ่งหนีได้ยังไงตอนนี้!",
  ui_story_5087_50870800_41_dialog_content = "มันคืออะไรนะ, เนโปลิส? อา! นายนี่เอง... ชาญ่า...",
  ui_story_5087_50870800_42_dialog_content = "ฉันจับได้โจรน้อยนี้ที่แอบตามคุณจากต้นไม้ เธอแน่นอนว่ากำลังคิดอะไรไม่ดี!",
  ui_story_5087_50870800_43_dialog_content = "แต่ไม่ต้องห่วง ฉันจับเธอได้ก่อนที่เธอจะทำอะไรได้! คุณปลอดภัยแล้ว!",
  ui_story_5087_50870800_44_dialog_content = "...",
  ui_story_5087_50870800_45_dialog_content = "นิคินิส... ช่วยฉัน...",
  ui_story_5087_50870800_46_dialog_content = "อะไรนะ? ค-คุณรู้จักกัน? เมื่อไหร่ที่เกิดเรื่องนี้ขึ้น? แล้วทำไมฉันถึงไม่ถูกบอกเล่าเรื่องนี้?",
  ui_story_5087_50870800_47_dialog_content = "เนโปลิส... ฉันขอโทษจริง ๆ",
  ui_story_5087_50870800_48_dialog_content = "อ๊ะ! ฉันไม่ได้โทษเธอหรอก—",
  ui_story_5087_50870800_49_dialog_content = "แต่ไม่ต้องกังวล ฉันจะบอกคุณทุกอย่างตอนนี้ ฉันจะไม่ปิดบังอะไรจากคุณอีกต่อไป ฉันสัญญา",
  ui_story_5087_50870800_50_dialog_content = "หลังจากนี้... ฉันจะต้องการภูมิปัญญาของคุณ",
  ui_story_5087_50870900_1_dialog_content = "ราชินีเบธเลเฮมเป็นคนปลอมหรือ?",
  ui_story_5087_50870900_2_dialog_content = "ใช่ หล่อนเป็นแค่ภาพลวงตาของแชโดว์ นั่นเป็นเหตุผลว่าทำไมเธอถึงแสดงออกอย่างรุนแรงเช่นนั้น",
  ui_story_5087_50870900_3_dialog_content = "การเรียกใช้กำลังของราชวงศ์ทั้งหมดเพื่อจับกุมโจรคนเดียว... เป็นการใช้พลังงานของเธออย่างไม่มีประสิทธิภาพเป็นอย่างยิ่ง",
  ui_story_5087_50870900_4_dialog_content = "ราชินีแท้ ๆ คงคิดอะไรที่ฉลาดกว่านี้มากเลยทีเดียว",
  ui_story_5087_50870900_5_dialog_content = "(แม้ว่าจะได้พบกับเธอครั้งที่สองแล้ว ผมยังคิดว่ามีบางอย่างที่เป็นเอกลักษณ์ของชาญ่าอยู่)",
  ui_story_5087_50870900_6_dialog_content = "(แม้จะเป็นเด็กหญิงที่ยังเด็กมาก แต่เธอมีบรรยากาศที่เป็นธรรม และเธอไม่มีความลังเลในการวิจารณ์สมเด็จพระราชินี)",
  ui_story_5087_50870900_7_dialog_content = "เป็นความจริงที่ว่าวิธีของสมเด็จย่ามีความแตกต่างบ้างในช่วงนี้ แต่นั่นก็ไม่ใช่เหตุผลที่จะสงสัยเธอ...",
  ui_story_5087_50870900_8_dialog_content = "ถ้าสิ่งที่คุณพูดเป็นความจริง ชาญ่า แล้วราชินีที่แท้จริงอยู่ที่ไหนนะ?",
  ui_story_5087_50870900_9_dialog_content = "... โดยทั่วไปแล้ว เบธเลเฮมมักจะใช้เวลาของเธอในโลกที่แตกต่างไป -- โลกที่อยู่ทางฝั่งตรงข้ามของกระจกเงาแดนเหนือ",
  ui_story_5087_50870900_10_dialog_content = "... คุณกำลังพูดว่ามีโลกที่แตกต่างอย่างสิ้นเชิงอยู่ข้างหลังกระจกแห่งนอร์ธแลนด์เหรอ?",
  ui_story_5087_50870900_11_dialog_content = "นี่หมายความว่าเหตุผลที่คุณขโมยกระจกเพื่อที่จะเดินทางไปโลกอื่นและค้นหาราชินีเบธเลเฮมแท้ ๆ หรือเปล่า?",
  ui_story_5087_50870900_12_dialog_content = "เหตุผลของคุณถูกต้อง... ใช่ ฉันต้องไปที่นั่นจริงๆ",
  ui_story_5087_50870900_13_dialog_content = "กระจกนอร์ธแลนด์เป็นทางผ่านที่สมบูรณ์แบบในการเดินทางระหว่างทั้งสองโลก",
  ui_story_5087_50870900_14_dialog_content = "แต่ตอนนี้มันเสียแล้ว ต้องซ่อมก่อนฉันจึงจะทำอะไรได้",
