  ui_story_5087_50871102_25_dialog_content = "ท่านหญิงนิคินิส ข้าไม่สามารถขอบคุณท่านพอเพียงสำหรับการสู้รบด้วยกันและปกป้องเราเสมอมา!",
  ui_story_5087_50871102_26_dialog_content = "(นั่น... คือความทรงจำของฉันเมื่อกี้เหรอ?)",
  ui_story_5087_50871102_27_dialog_content = "(ฉันเคยทรงคุณค่าและสงบสุขขนาดนั้นเหรอ? ฉันเคยมีส่วนร่วมในเหตุการณ์สำคัญๆเยอะแยะเหรอ?)",
  ui_story_5087_50871102_28_dialog_content = "<color=#e8d9bb>เหมือนถูกดึงดูดโดยความทรงจำที่เธอได้คืนมา นิคินิสเดินเข้าหากระจกนอร์ธแลนด์อย่างช้าๆ และวางฝ่ามือของเธอลงบนมัน—</color>",
  ui_story_5087_50871102_29_dialog_content = "มันกลับมาสมบูรณ์อีกครั้ง! ... คุณมีความสัมพันธ์พิเศษกับมันจริงๆ นิคินิส",
  ui_story_5087_50871102_30_dialog_content = "อืม...",
  ui_story_5087_50871102_31_dialog_content = "นี่เป็นสิ่งที่ดี ตอนนี้เหลือเพียงขั้นตอนสุดท้ายเท่านั้น!",
  ui_story_5087_50871102_32_dialog_content = "ขั้นตอนสุดท้ายหรือ? คุณไม่ได้บอกว่าทุกอย่างจะถูกเปิดเผยเมื่อกระจกได้รับการซ่อมแซมแล้วหรือ?",
  ui_story_5087_50871102_33_dialog_content = "นิคินิส คุณควรจะสามารถเรียกความทรงจำบางส่วนของคุณกลับมาได้ในขณะที่ซ่อมแซมกระจกเงา",
  ui_story_5087_50871102_34_dialog_content = "ตอนนี้... สิ่งที่เหลือก็คือ <color=#FFB400>ผ่านไปทางกระจก</color>!",
  ui_story_5087_50871102_35_dialog_content = "อะไร? ผ่านไปยังโลกอื่น?",
  ui_story_5087_50871102_36_dialog_content = "ถูกต้อง นั่นคือที่ที่ราชินีเบธเลเฮมแท้จริงอาศัยอยู่ ความทรงจำที่คุณยังคงมีและคำตอบที่คุณกำลังมองหาก็อยู่ทางนั้นเหมือนกัน อยู่เลยนอกกระจก!",
  ui_story_5087_50871102_37_dialog_content = "ฉันไม่รู้...",
  ui_story_5087_50871102_38_dialog_content = "ทำมันสิ นิคินิส",
  ui_story_5087_50871102_39_dialog_content = "ฮะ? คุณต้องการให้ฉันเข้าไปในกระจกหรือ?",
  ui_story_5087_50871102_40_dialog_content = "ถูกต้องแล้ว เรามาไกลแล้ว เราไม่สามารถเพียงหันกลับแล้วกลับบ้านได้ ใช่มั้ย?",
  ui_story_5087_50871102_41_dialog_content = "คุณต้องรื้อฟื้นความทรงจำของคุณ ความเข้าใจทุกอย่าง และกลับมาบอกฉันรายละเอียดทุกอย่าง",
  ui_story_5087_50871102_42_dialog_content = "ถ้ากระจกนั่นกล้าหยุดคุณ ฉันจะไม่หยุดนิ่งจนกว่าจะนำคุณกลับมา และเราจะโชว์ให้มันรู้ว่าใครคือบอส!",
  ui_story_5087_50871102_43_dialog_content = "งั้น รีบ ๆ เอามาเถอะน่า! สัญญาแล้วนะ!",
  ui_story_5087_50871102_44_dialog_content = "เนโปลิส...",
  ui_story_5087_50871102_45_dialog_content = "...",
  ui_story_5087_50871102_46_dialog_content = "เอาสิ นิคินิส",
  ui_story_5087_50871102_47_dialog_content = "ฉ-ฉันจะไปแล้วนะ, เนโปลิส!",
  ui_story_5087_50871102_48_dialog_content = "เอางั้นก็ได้ครับ",
  ui_story_5087_50871102_49_dialog_content = "<color=#e8d9bb>กระจกเริ่มส่องสว่างขึ้นเหมือนกำลังต้อนรับนิคินิส และเธอก็ในที่สุดได้ก้าวขาไป—</color>",
  ui_story_5087_50871102_50_dialog_content = "<color=#e8d9bb>ฉ่า.</color>",
  ui_story_5087_50871102_51_dialog_content = "อืม... โอ๊ย! อย่าแม้... แต่จะคิดเชียวนะ!",
  ui_story_5087_50871102_52_dialog_content = "เกิดอะไรขึ้น เนโปลิส?",
  ui_story_5087_50871102_53_dialog_content = "ฉัน... สบายดี... เร่ง... อ๊ากกกก!",
  ui_story_5087_50871102_54_dialog_content = "...",
  ui_story_5087_50871102_55_dialog_content = "เนโปลิส! เนโปลิส! นายไม่เป็นไรนะ?",
  ui_story_5087_50871102_56_dialog_content = "นิคินิส! อย่าเข้าใกล้พี่สาวของเธอ! ฉันกลัวว่าเธอ—",
  ui_story_5087_50871102_57_dialog_content = "... นิคินิส.",
  ui_story_5087_50871102_58_dialog_content = "ฉันอยู่ตรงนี้นะ! คุณรู้สึกอย่างไรบ้าง? บาดเจ็บตรงไหนรึเปล่า?",
  ui_story_5087_50871102_59_dialog_content = "ฝั่งตรงข้ามของกระจก... มันอันตรายมากจริง ๆ",
  ui_story_5087_50871102_60_dialog_content = "ห๊ะ",
  ui_story_5087_50871102_61_dialog_content = "ฉันไม่สามารถปล่อยให้คุณไปที่สถานที่อันตรายแบบนั้นได้ อยู่ข้างฉันไว้นะ อย่าไปไหน โอเคไหม?",
  ui_story_5087_50871102_62_dialog_content = "B-แต่... คุณเพิ่งพูดว่า...",
  ui_story_5087_50871102_63_dialog_content = "ฉันกลัว... ฉันกลัวว่าจะสูญเสียคุณ... หากคุณผ่านไปทางกระจก ฉันจะไม่เห็นคุณอีกเลย",
  ui_story_5087_50871102_64_dialog_content = "ทั้งหมดที่ฉันต้องการคือคุณ และฉันคิดว่าคุณก็รู้สึกเหมือนกันใช่มั้ย?",
  ui_story_5087_50871102_65_dialog_content = "คุณจะรู้สึกเหงามากถ้าไม่มีฉัน... คุณยังไม่สามารถที่จะเผชิญกับรอยยิ้มของผู้คนในปาร์ตี้เลย",
  ui_story_5087_50871102_66_dialog_content = "!",
  ui_story_5087_50871102_67_dialog_content = "ยิ่งคนอื่นมีความสุขมากเท่าไหร่ คุณก็ยิ่งรู้สึกเจ็บปวดมากขึ้น เพราะในใจที่สุดลึก คุณรู้ว่าความสุขของคุณจะไม่มีวันกลับมาอีก...",
  ui_story_5087_50871102_68_dialog_content = "อยู่กับฉันสิ พี่สาวของฉัน... นิคินิสของฉัน—",
  ui_story_5087_50871102_69_dialog_content = "นิคินิส อย่าให้เธอหลอกลวงคุณ คนนั้นไม่ใช่พี่สาวของคุณอีกต่อไป!",
  ui_story_5087_50871102_70_dialog_content = "คุณต้องผ่านไปทางกระจก! คุณอยู่ใน<color=#FFB400>โลกกระจก</color>ที่ถูกสร้างขึ้นโดยกระจกแห่งนอร์ธแลนด์! และด้านนี้—",
  ui_story_5087_50871102_71_dialog_content = "นี่คือที่ที่ <color=#FFB400>ความเป็นจริง</color> อยู่อย่างแท้จริง!",
  ui_story_5087_50871102_72_dialog_content = "!",
  ui_story_5087_50871102_73_dialog_content = "คุณยังไม่สังเกตเหรอ? ไม่มีอะไรในโลกนี้ดูถูกต้องเลย!",
  ui_story_5087_50871102_74_dialog_content = "มีบางอย่างไม่ถูกต้อง... ใช่, ฉันไม่เคยจำได้ว่าพ่อแม่ฉันเคยทำงานที่พระราชวังฤดูหนาว...",
  ui_story_5087_50871102_75_dialog_content = "เพราะมันถูกสร้างขึ้นโดยกระจกนอร์ธแลนด์!",
  ui_story_5087_50871102_76_dialog_content = "พระราชวังเหมันต์...สะอาดเกินไป",
  ui_story_5087_50871102_77_dialog_content = "เพราะที่นี่ไม่มีแชโดว์เลย! ทุกอย่างที่นี่คือภาพลวงตาที่ไม่มีเงาที่กระจกสร้างขึ้น! แม้กระทั่งสมเด็จพระราชินีก็เป็นแค่ภาพลวงตา!",
  ui_story_5087_50871102_78_dialog_content = "มันเป็นความจริง! เทียนและเฟอร์นิเจอร์ไม่มีเงา แต่ฉันมี! และเนโปลิส...",
  ui_story_5087_50871102_79_dialog_content = "... รอสักครู่! คุณผิด! เนโปลิสมีเงา! เธอเป็นตัวจริง!",
  ui_story_5087_50871102_80_dialog_content = "... ชาญ่ายังไม่มาถึงหรือ? เธอจะอธิบายทุกอย่างให้คุณฟัง! ในตอนนี้ ฉันคิดว่าฉันสามารถบอกความจริงให้คุณฟังได้แล้ว ชาญ่าคือเบธ—",
  ui_story_5087_50871102_81_dialog_content = "เธอไม่มา",
  ui_story_5087_50871102_82_dialog_content = "คุณ—",
  ui_story_5087_50871102_83_dialog_content = "<color=#e8d9bb>นิคินิสส่งสายตาไปที่เท้าของสมเด็จพระราชินีโดยสัญชาตญาณ ไม่มีอะไรอยู่ที่นั่น และยังไม่มีอะไรอยู่ที่เท้าของทหารยามด้วย</color>",
  ui_story_5087_50871102_84_dialog_content = "<color=#e8d9bb>ไม่มีอะไรเลย! ไม่มีอะไรอยู่ที่นั่น! พวกเขาไม่มีเงาเลย!</color>",
  ui_story_5087_50871102_85_dialog_content = "<color=#e8d9bb>\"ควีน\" ทำให้กระจกนอร์ธแลนด์แช่แข็งด้วยการสะบัดฝ่ามือของเธอ และด้วยการสะบัดอีกครั้ง กระจกก็บินออกไปและแตกเป็นชิ้นเล็กๆ</color>",
  ui_story_5087_50871102_86_dialog_content = "... ดังนั้นคุณคือคนปลอม!",
  ui_story_5087_50871102_87_dialog_content = "ฉันไม่ใช่คนเดียว ทุกคนออกมาซิ!",
  ui_story_5087_50871102_88_dialog_content = "Graaah!",
  ui_story_5087_50871102_89_dialog_content = "อย่าแม้แต่จะคิดเชียวนะ! ฉันจะไม่ให้นายทำร้ายเนโพลิส—",
  ui_story_5087_50871102_90_dialog_content = "เนโปลิส? เฮ้, คุณตรวจสอบเรื่องที่ฉันสะกดรอย แต่คุณไม่ทำเช่นนั้นกับเธอเหรอ?",
  ui_story_5087_50871102_91_dialog_content = "ไม่... เธอแตกต่าง...",
  ui_story_5087_50871102_92_dialog_content = "ก้า! ก้าาา!",
  ui_story_5087_50871102_93_dialog_content = "ทำไมฉันถึงต้องประดิษฐ์ชีวิตของพ่อแม่ของคุณ? เพราะพวกเขามีชีวิตอยู่ในโลกนี้เท่านั้น!",
  ui_story_5087_50871102_94_dialog_content = "เหมือนกับเนโปลิสนั่นแหละ",
  ui_story_5087_50871102_95_dialog_content = "ไม่... หยุดนะ!",
  ui_story_5087_50871102_96_dialog_content = "... โอ้ พวกเรารู้จักกันมานานแล้วนะ ฉันคิดว่าคุณฉลาดกว่านี้",
  ui_story_5087_50871102_97_dialog_content = "เอาล่ะ ฉันจะจับคุณก่อน แล้วค่อย ๆ ทำให้คุณเผชิญหน้ากับความเป็นจริง",
  ui_story_5087_50871102_98_dialog_content = "รับเธอ! ไม่เป็นไรถ้าคุณหยาบคายหน่อย!",
  ui_story_5087_50871102_99_dialog_content = "Graaah!",
  ui_story_5087_50871102_100_dialog_content = "<color=#e8d9bb>อื้อหือ! การโจมตีที่รุนแรงที่สุดไม่ได้ตกลงบนนิคินิส</color>",
  ui_story_5087_50871102_101_dialog_content = "เนโพลิส?",
  ui_story_5087_50871102_102_dialog_content = "<color=#e8d9bb>นิคินิสมองเห็นสิ่งมืดๆและไม่ชัดเจนไหลออกจากแผลของเนโปลิส—</color>",
  ui_story_5087_50871102_103_dialog_content = "<color=#e8d9bb>แล้วเธอก็เริ่มละลายที่นั่นเลย</color>",
  ui_story_5087_50871102_104_dialog_content = "ไม่... นี่ไม่ใช่เรื่องจริง... เนโปลิส... เนโปลิส!",
  ui_story_5087_50871102_105_dialog_content = "น-นิคินิส...",
  ui_story_5087_50871102_106_dialog_content = "เนโปลิส... ไม่! ไม่... ได้โปรดอย่าไป—",
  ui_story_5087_50871102_107_dialog_content = "ว-วิ่ง!",
  ui_story_5087_50871102_108_dialog_content = "!",
  ui_story_5087_50871102_109_dialog_content = "<color=#e8d9bb>มอนสเตอร์มากมายพุ่งไปข้างหน้าและกวาดไปพร้อมกับรูปทรงเงาของ Nepolis.</color>",
  ui_story_5087_50871102_110_dialog_content = "ไม่! คุณไปไหนแล้วนะ, เนโปลิส?",
  ui_story_5087_50871102_111_dialog_content = "<color=#e8d9bb>นิคินิสจับอย่างประสาท แต่ที่เหลืออยู่เพียงแค่เงามืดที่หายไปในการจับของเธอ</color>",
  ui_story_5087_50871102_112_dialog_content = "เนโปลิส... เนโปลิส...",
  ui_story_5087_50871102_113_dialog_content = "ฮึบบบบ!",
  ui_story_5087_50871102_114_dialog_content = "...",
  ui_story_5087_50871102_115_dialog_content = "ทั้งหมดเป็นความผิดของคุณ! คุณเหล่าสัตว์ประหลาด!",
  ui_story_5087_50871102_116_dialog_content = "กรร...",
  ui_story_5087_50871102_117_dialog_content = "คุณได้รับกลับส่วนหนึ่งของพลังงานจากความเป็นจริงเหรอ?",
  ui_story_5087_50871102_118_dialog_content = "เนโพลิส คุณอยู่ที่ไหน? โปรดอย่าทำให้ฉันกลัวแบบนี้... โอ้ คุณไปข้างหน้าเพื่อเปิดทางให้ฉันใช่ไหม? ฮือ คุณควรจะบอกฉัน...",
  ui_story_5087_50871102_119_dialog_content = "ฉันกำลังไปหาคุณ!",
  ui_story_5087_50871102_120_dialog_content = "เนโพลิส—",
  ui_story_5087_50871102_121_dialog_content = "เนโปลิส...",
  ui_story_5087_50871102_122_dialog_content = "เนโปลิส คุณอยู่ที่ไหน? ฉันขอร้องคุณ! โปรดกลับมาหาฉัน...",
  ui_story_5087_50871102_123_dialog_content = "<color=#e8d9bb>โดยที่นิคินิสไม่รู้ตัวเอง เธอถึงที่กระท่อมที่เธอเคยค้นพบกระจกนอร์ธแลนด์กับเนโปลิส</color>",
  ui_story_5087_50871102_124_dialog_content = "เนโปลิส คุณมาที่นี่เพื่อรอฉันหรือ?",
  ui_story_5087_50871102_125_dialog_content = "<color=#e8d9bb>ในกลิ่นหอมที่ท่วมท้นจากดอกไม้ ดอกไม้สีขาวบริสุทธิ์ที่ทำจากลูมินาติกส์ยังคงบานเต็มที่ภายในกระท่อม</color>",
  ui_story_5087_50871102_126_dialog_content = "<color=#e8d9bb>แต่มีแต่นาร์ซิสซัสสีขาวที่ยังคงอยู่ ทุกดอกเป็นนาร์ซิสซัสสีขาว</color>",
  ui_story_5087_50871102_127_dialog_content = "<color=#e8d9bb>ดอกลิลลี่ทั้งหมดหายไป ดูเหมือนว่าพวกมันไม่เคยมีอยู่เลยตั้งแต่แรก</color>",
  ui_story_5087_50871102_128_dialog_content = "เนโพลิส?",
  ui_story_5087_50871102_129_dialog_content = "\"คุณจำดอกไม้สีขาวที่สวยงามนั้นได้ไหม? สองต้นที่เติบโตอยู่ด้วยกันอย่างสมดุลย์ที่ทะเลสาบที่สงบนิ่ง.\"",
  ui_story_5087_50871102_130_dialog_content = "เปล่านะ เปล่า เปล่า...",
  ui_story_5087_50871102_131_dialog_content = "\"ภายใต้หิมะสีเทาที่ตกหนัก ดอกลิลลี่ที่สะอาดเนียนก็ถูกกลบซ่อนไปอย่างรวดเร็ว\"",
  ui_story_5087_50871102_132_dialog_content = "\"ถูกทิ้งเอาไว้คนเดียวในโลกนี้ นาร์ซิสซัสสีขาวร้องไห้อย่างเงียบ ๆ\"",
  ui_story_5087_50871102_133_dialog_content = "... โฮวววววววว!",
  ui_story_5087_50871200_1_dialog_content = "แปลกจัง",
  ui_story_5087_50871200_2_dialog_content = "คุณพ่อและคุณแม่บอกว่าเธอได้ไปแล้ว แต่เนโปลิสมักอยู่ข้างฉันเสมอ",
  ui_story_5087_50871200_3_dialog_content = "<color=#e8d9bb>ซ่า... แมลงวันบินลงบนเนื้อสีแดงที่กำลังสูญเสียรูปร่างอยู่</color>",
  ui_story_5087_50871200_4_dialog_content = "กลิ่นนั่น... อ๊ะ! นั่นของแกงแอปเปิ้ลจากสัปดาห์ที่แล้วเหรอ? มันทำอะไรอยู่ที่นั่น นิคินิส?",
  ui_story_5087_50871200_5_dialog_content = "ถึงคุณจะไม่อยากกิน ก็อย่างน้อยก็ทิ้งของเหลือทิ้งไว้! ดูสิ...",
  ui_story_5087_50871200_6_dialog_content = "แต่... นั่นเป็นส่วนของเนโปลิส",
  ui_story_5087_50871200_7_dialog_content = "!",
  ui_story_5087_50871200_8_dialog_content = "แปลกจัง ทำไมเนโปลิสถึงไม่กินล่ะ? สตูว์แอปเปิ้ลนี่เป็นอาหารที่เธอชอบที่สุดนี่นา.",
  ui_story_5087_50871200_9_dialog_content = "ฉันรู้! คงเป็นเพราะเธอไม่ค่อยมีความอยากทานอาหารเลยในช่วงนี้! แถมยังพูดน้อยลงอีก... หรือเป็นผลข้างเคียงจากการป่วยหรือเปล่า?",
  ui_story_5087_50871200_10_dialog_content = "เจอแล้ว! ต่อไปคือใคร?",
  ui_story_5087_50871200_11_dialog_content = "เฮ้! ให้เราเข้าร่วมกับพวกคุณสิ!",
  ui_story_5087_50871200_12_dialog_content = "หา? แต่คุณอยู่คนเดียวเลยนะ.",
  ui_story_5087_50871200_13_dialog_content = "คุณหมายถึงอะไร? พี่สาวของฉันอยู่ข้างๆฉันนี่แหละ! เธอพูดน้อยลงในช่วงนี้ แต่ฉันรู้ว่าเธออยากเล่นกับทุกคน!",
  ui_story_5087_50871200_14_dialog_content = "Luminatics ของเราถูกเชื่อมต่อกัน ดังนั้นฉันรู้ทุกอย่างที่เธอคิด",
  ui_story_5087_50871200_15_dialog_content = "... เธอบ้า",
  ui_story_5087_50871200_16_dialog_content = "นิคินิสเป็นคนบ้า! เธอเป็นคนบ้าสุดๆ!",
  ui_story_5087_50871200_17_dialog_content = "คุณบ้าแล้ว! คุณเป็นคนบ้า! พี่สาวฉันเพียงแค่ป่วย และทำให้ลูมินาของเธออ่อนแอ! เธออยู่ที่นั่นตลอดเวลา! ฉันเห็นเธออยู่!",
  ui_story_5087_50871200_18_dialog_content = "ฝ่าบาท ข้าขอร้องครับ ช่วยนิคินิสด้วยครับ! ตั้งแต่เนโปลิส... คุณรู้อยู่แล้ว นางก็เป็นแบบนี้ตั้งแต่เวลานั้น...",
  ui_story_5087_50871200_19_dialog_content = "แพทย์ทุกคนตกใจ! คุณคือความหวังสุดท้ายของเรา! ฉันขอร้องคุณ ฝ่าบาท!",
  ui_story_5087_50871200_20_dialog_content = "... สถานการณ์ของลูกสาวคู่แฝดของคุณนั้นเป็นกรณีที่หายากมาก.",
  ui_story_5087_50871200_21_dialog_content = "ฉันมีความคิด แต่มันอันตรายเกินไป ขอให้ฉันคิดเพิ่มเติมอีกสักหน่อย",
  ui_story_5087_50871200_22_dialog_content = "ชื่อของคุณคือนิคินิสใช่ไหม? ชื่อที่สวยงามจริงๆ แต่เนื่องจากพี่สาวของคุณ นีโปลิส ไม่ชอบการพูดคุย คุณสามารถแนะนำเธอให้ฉันรู้จักได้ไหม?",
  ui_story_5087_50871200_23_dialog_content = "คุณ... ถามถึงน้องสาวของฉันเหรอ? ขอบคุณสวรรค์! ในที่สุดก็มีคนเชื่อฉัน!",
  ui_story_5087_50871200_24_dialog_content = "แต่คุณจะรักษาเธอก่อนได้ไหม? เธอป่วย และเธอยังไม่ได้ฟื้นตัวสมบูรณ์จนถึงตอนนี้...",
  ui_story_5087_50871200_25_dialog_content = "วิญญาณของเราเป็นหนึ่งเดียวกัน ดังนั้นการรักษาฉันคนเดียวไม่มีผล... ฉันจะสบายดีเมื่อเธอสบายดี!",
  ui_story_5087_50871200_26_dialog_content = "...",
  ui_story_5087_50871200_27_dialog_content = "นีโปลิส, นีโปลิส! สมเด็จพระเจ้าหญิงแน่นอนจะสามารถรักษาคุณได้! นี่เป็นข่าวที่ดีมาก!",
  ui_story_5087_50871200_28_dialog_content = "ใช่... ฉันก็รู้สึกดีใจมากเหมือนกัน...",
  ui_story_5087_50871200_29_dialog_content = "งั้น มาเล่นซ่อนหากันมั้ย? ไม่ใช่ทุกวันที่เราจะได้พักคืนที่วังหิมะ มาสนุกกันเถอะ!",
  ui_story_5087_50871200_30_dialog_content = "ที่นี่มีความลึกลับมากจริง ๆ... เนโปลิส, คุณรู้สึกเหมือนฉันไหม?",
  ui_story_5087_50871200_31_dialog_content = "...",
  ui_story_5087_50871200_32_dialog_content = "ออโรเรียนน้อย... ออโรเรียนน้อยทางนั้น...",
  ui_story_5087_50871200_33_dialog_content = "ฮะ? ใครอยู่ที่นั่น? เธอกำลังคุยกับใคร? ฉันเหรอ? หรือน้องสาวฉัน?",
  ui_story_5087_50871200_34_dialog_content = "เธอเท่านั้นที่สามารถเห็นพี่สาวของเธอและรับรู้ถึงวิญญาณของเธอ มันเหงาใช่มั้ยนะ ออโรเรียนน้อย...",
  ui_story_5087_50871200_35_dialog_content = "!",
  ui_story_5087_50871200_36_dialog_content = "ฉัน... สามารถช่วยคุณได้ มาใกล้ ๆ สิ...",
  ui_story_5087_50871200_37_dialog_content = "... กระจก? กระจกจะช่วยฉันได้อย่างไร?",
  ui_story_5087_50871200_38_dialog_content = "ออโรเรียนน้อย ๆ คุณไม่รู้อะไรเลยเกี่ยวกับพลังของกระจก",
  ui_story_5087_50871200_39_dialog_content = "ฉันสามารถทำให้น้องสาวของคุณกลับมาสู่ความยิ่งใหญ่เดิม ทุกคนจะสามารถเห็นและรับรู้ถึงเธอ—",
  ui_story_5087_50871200_40_dialog_content = "แต่คุณต้องทำสัญญากับฉัน",
  ui_story_5087_50871200_41_dialog_content = "จ-จริงหรือเนี่ย? เธอจะเล่นกับฉัน, ล้อเล่นฉัน, และทะเลาะกับฉัน, เหมือนที่เธอเคยทำในอดีตเหรอ?",
  ui_story_5087_50871200_42_dialog_content = "ฉันต้องทำอย่างไร?",
  ui_story_5087_50871200_43_dialog_content = "ให้ฉัน... ลูมินาของคุณ.",
  ui_story_5087_50871200_44_dialog_content = "ลูมินาของฉัน? แบบนี้หรือ?",
  ui_story_5087_50871200_45_dialog_content = "<color=#e8d9bb>ฝ่ามือเล็ก ๆ ของเธอปิดกระจก—</color>",
  ui_story_5087_50871200_46_dialog_content = "ของสะสมถูกปลุกขึ้นแล้ว! มันกำลังดูดซับลูมินา... แจ้งฝ่าบาททันที!",
  ui_story_5087_50871200_47_dialog_content = "เด็กคนนั้น นิคินิส... เธอยังหมดสติอยู่ กระจกนอร์ธแลนด์ดูดลูมินาจากเธอไปเยอะเกินไป",
  ui_story_5087_50871200_48_dialog_content = "เธอจะตื่นขึ้นมาอีกไหม?",
  ui_story_5087_50871200_49_dialog_content = "กระจกนอร์ธแลนด์ได้เลือกเธอเป็นเจ้าภาพ โอกาสในการอยู่รอดของเธอนั้นบางมาก",
  ui_story_5087_50871200_50_dialog_content = "... นอกจากนี้ฉันจะต้องผนึกร่างของเธอด้วยกระจกนอร์ธแลนด์",
  ui_story_5087_50871200_51_dialog_content = "ถ้าเธอสามารถปรับตัวเข้ากับของสืบสันดานและฟื้นสำนึกด้วยตัวเองได้ เธอจะรอด มิฉะนั้น...",
  ui_story_5087_50871200_52_dialog_content = "ฉันเดาว่านั่นคือวิธีแก้เดียว...",
  ui_story_5087_50871200_53_dialog_content = "*หัวร่วง* นี่แหละสถานการณ์ที่คุณพยายามหลีกเลี่ยงโดยไม่ใช้กระจกนอร์ธแลนด์รักษาเธอ",
  ui_story_5087_50871200_54_dialog_content = "เราไม่เคยรู้ว่า \"กระจกนอร์ธแลนด์\" จะดึงดูดเธอ... เธอนั้นเข้ากันได้กับมันจริงหรือ?",
  ui_story_5087_50871200_55_dialog_content = "คุณไม่สามารถเรียกว่า \"การรักษา\" นั่นเพียงการใช้พลังของ \"กระจกนอร์ธแลนด์\" ในสาขาจิตวิทยาเท่านั้นเองที่—",
  ui_story_5087_50871200_56_dialog_content = "บังคับลบคงเหลือของ Luminatics ที่ถูกทิ้งไว้โดยพี่สาวที่เสียชีวิตของเธอ",
  ui_story_5087_50871200_57_dialog_content = "ลูมินาติกส์ของพี่สาวคนหนึ่งที่ยังคงอยู่ในพี่สาวคนอื่นนั้น มันน่าอัศจรรย์จริง ๆ นะ",
  ui_story_5087_50871200_58_dialog_content = "นิคินิสและนีโปลิสเป็นพิเศษ ความสัมพันธ์ของพวกเขาใกล้ชิดมากจนเหมือนว่ามีจิตวิญญาณเดียวแบ่งออกเป็นสองร่างกาย",
  ui_story_5087_50871200_59_dialog_content = "นั่นเป็นเหตุผลที่การรักษาของนิคินิสต้องดำเนินการอย่างระมัดระวังมาก ถ้าส่วนที่เหลือของพี่สาวถูกนำออกอย่างบังคับ—",
  ui_story_5087_50871200_60_dialog_content = "แม้ว่าเธอจะไม่ได้\"เห็น\"พี่สาวของเธออีกครั้ง แต่เวลาที่พวกเขาได้ใช้เวลาด้วยกัน ความทรงจำที่พวกเขาได้แบ่งปันกัน และความรู้สึกที่พวกเขาสร้างขึ้นด้วยกัน...",
  ui_story_5087_50871200_61_dialog_content = "ทุกอย่างจะถูกทำให้ยุ่งเหยิงหรือหายไปเลย",
  ui_story_5087_50871200_62_dialog_content = "มันจะไม่ต่างจากการถอดครึ่งหนึ่งของเธอออกไป",
  ui_story_5087_50871200_63_dialog_content = "ใช่ ความเสี่ยงนั้นเป็นไปไม่ได้ที่จะกำจัดได้ แม้แต่ด้วยความช่วยเหลือจากกระจกนอร์ธแลนด์ก็ตาม",
  ui_story_5087_50871200_64_dialog_content = "แฝดสองคนที่เชื่อมต่อทั้งจิตใจและวิญญาณ แต่พี่สาวก็ป่วย...",
  ui_story_5087_50871200_65_dialog_content = "และความตายแยกพวกเขาออกจากกัน... ทำไมชะตากรรมถึงชอบล้อเล่นกับเราทั้งหมดอย่างนี้?",
  ui_story_5087_50871200_66_dialog_content = "... แต่พวกเขาจริงๆ แยกกันหรือไม่?",
  ui_story_5087_50871200_67_dialog_content = "โนวิโอ, คุณเชื่อหรือไม่ว่า... วิญญาณของออโรเรียนอยู่ภายใน Luminatics?",
  ui_story_5087_50871300_1_dialog_content = "(ฉันจำได้แล้ว, ทั้งหมดเลย)",
  ui_story_5087_50871300_2_dialog_content = "(Nepolis ได้สิ้นชีพไปนานแล้ว และราชินีเบธเลเฮมได้ปิดผนึกฉันไว้ในถ้ำแข็งเพื่อช่วยชีวิตฉัน)",
  ui_story_5087_50871300_3_dialog_content = "(แม่และพ่อทั้งคู่เสียชีวิตในช่วงเวลานี้)",
  ui_story_5087_50871300_4_dialog_content = "(ฉันแทบจะจำไม่ได้เลยว่าเคยอยู่กับพ่อแม่หลังจากที่ฉันฟื้นสติ...)",
  ui_story_5087_50871300_5_dialog_content = "<color=#e8d9bb>เมื่อเปิดตาขึ้นในถ้ำที่แข็งเป็นน้ำแข็ง ออโรเรียนที่รู้จักกันในนามนิคินิสไม่มีอะไรเหลือเลย</color>",
  ui_story_5087_50871300_6_dialog_content = "<color=#e8d9bb>ไม่มีบ้าน ไม่มีบ้านเกิด หรือความทรงจำ เธออยู่คนเดียวในโลกนี้ด้วยตัวเองที่แ fragile และไม่สมบูรณ์</color>",
  ui_story_5087_50871300_7_dialog_content = "<color=#e8d9bb>นอกจากแสงอ่อน ๆ จากกระจกเวทมนตร์ที่อยู่ข้างเธอ สิ่งเดียวที่มารับเธอคือ—</color>",
  ui_story_5087_50871300_8_dialog_content = "<color=#e8d9bb>ภาพสะท้อนของตัวเองที่ยิ้มอยู่ กำลังเดินออกมาจากกลางดอกลิลลี่ที่บานเต็มที่ ที่สะท้อนบนผิวกระจก</color>",
  ui_story_5087_50871300_9_dialog_content = "\"คุณมองอะไรอยู่? ไม่รู้จักพี่สาวของคุณเองหรือ?\"",
  ui_story_5087_50871300_10_dialog_content = "\"นิคินิสของฉัน... ครึ่งอีกฝั่งของฉัน...\"",
  ui_story_5087_50871300_11_dialog_content = "(ทั้งหมดนี้... นี่คือความเป็นจริงของฉัน...)",
  ui_story_5087_50871300_12_dialog_content = "(ความจริงที่โหดร้ายและน่ากลัวมากกว่าโลกกระจก)",
  ui_story_5087_50871300_13_dialog_content = "แล้วทำไมคุณไม่อยู่ในกระจกล่ะ?",
  ui_story_5087_50871300_14_dialog_content = "...",
  ui_story_5087_50871300_15_dialog_content = "คุณอีกแล้ว... ยังกล้าพูดกับฉันอย่างไม่มีเกรงใจอีกหรือ...",
  ui_story_5087_50871300_16_dialog_content = "เป็นความผิดแกทั้งหมด!",
  ui_story_5087_50871300_17_dialog_content = "อย่าวิจารณ์มากเกินไป... ฉันแค่ทำให้ความปรารถนาของคุณเป็นจริงเท่านั้นเอง",
  ui_story_5087_50871300_18_dialog_content = "คุณต้องการที่จะสนุกสนานกับชีวิตร่วมกับพี่สาวของคุณ และฉันได้ให้คุณสิ่งนั้น คุณต้องการที่จะสู้รบเคียงข้างพี่สาวของคุณ และฉันก็ได้ให้คุณสิ่งนั้นเช่นกัน",
  ui_story_5087_50871300_19_dialog_content = "แม้ความทรงจำของความจริงที่คุณพยายามจะกู้คืน ฉันก็ได้ให้มันให้คุณเช่นกัน—แม้ว่ามันจะไม่เป็นประโยชน์ต่อฉันในทางใดทางหนึ่ง",
  ui_story_5087_50871300_20_dialog_content = "โอ้ ฉันหวังว่าคุณจะแสดงความขอบคุณบ้าง ผู้เจ้าภาพและผู้รับเหมาของฉัน...",
