  ui_story_5087_50871601_16_dialog_content = "\"คุณจำดอกไม้สีขาวที่สวยงามนั้นได้ไหม? คู่หนึ่งที่เติบโตอย่างสมดุลกับทะเลสาบที่สงบนิ่ง.\"",
  ui_story_5087_50871601_17_dialog_content = "...",
  ui_story_5087_50871601_18_dialog_content = "\"PlayerName, ฉันจำได้แล้ว.\"",
  ui_story_5087_50871601_19_dialog_content = "\"มันเป็นแค่ความทรงจำสั้น ๆ ของพ่อแม่ที่เล่าเรื่องให้เราฟังเท่านั้นเอง\"",
  ui_story_5087_50871601_20_dialog_content = "\"แต่ฉันมั่นใจว่าความทรงจำนี้เองกำลังซ่อนความจริงที่อยู่เบื้องหลังความทรงจำที่หายไปของฉัน...\"",
  ui_story_5087_50871601_21_dialog_content = "\"ทำไมฉันจำไม่ได้ว่าฉันอาศัยอยู่กับพ่อแม่ของฉัน?\"",
  ui_story_5087_50871601_22_dialog_content = "\"ทำไมเนโพลิสถึงถูกจำกัดให้อยู่ในกระจกเท่านั้น?\"",
  ui_story_5087_50871601_23_dialog_content = "\"ทำไมฉันต้องรู้สึกเศร้าสม่ำเสมอ กับมันเหมือนมีหลุมลึกไร้ท底อยู่ในหัวใจฉันเสมอเลยนะ?\"",
  ui_story_5087_50871601_24_dialog_content = "\"คำตอบที่ฉันกำลังค้นหาอย่างแน่นอนถูกซ่อนอยู่ในกระจกวิเศษที่ไม่เคยออกจากข้างฉัน...\"",
  ui_story_5087_50871601_25_dialog_content = "\"ดังนั้น ฉันกำลังจะเดินเข้าไปในกระจก เนโพลิสอยู่ที่นั่น และฉันกำลังจะไปอยู่ด้านของเธอในที่สุด\"",
  ui_story_5087_50871601_26_dialog_content = "\"ขอบคุณนะ, PlayerName.\"",
  ui_story_5087_50871601_27_dialog_content = "นั่นคือทั้งหมดที่ฉันมีในข้อความนี้",
  ui_story_5087_50871601_28_dialog_content = "<color=#e8d9bb>กระจกที่อยู่ข้างหน้ารออยู่ด้วยแสงสว่างอ่อนโยน เหมือนกับวันที่นิคินิสตื่นขึ้นในถ้ำที่แข็งเกลือ</color>",
  ui_story_5087_50871601_29_dialog_content = "<color=#e8d9bb>นิคินิสหายใจลึก ๆ แล้วก้าวไปข้างหน้าสู่ภาพสะท้อนของตัวเอง...</color>",
  ui_story_5087_50871601_30_dialog_content = "(นั่นคือวิธีที่ฉันเดินเข้าสู่โลกกระจกและตื่นขึ้นในทุ่งดอกไม้นี้...)",
  ui_story_5087_50871601_31_dialog_content = "(ฉันเดินเล่นจับมือกับพี่สาวและได้สัมผัสความสุขที่ไม่มีความกังวลที่สถานที่นี้มอบให้)",
  ui_story_5087_50871601_32_dialog_content = "(ถ้าฉันสามารถหลงไปในความฝันนี้ได้... แต่—)",
  ui_story_5087_50871601_33_dialog_content = "นิคินิสครับ, ฉันเอาหัวลิลลี่ใหม่มาให้คุณ พวกเราสามารถปลูกไว้ที่พื้นที่ว่างๆ ที่นั่น!",
  ui_story_5087_50871601_34_dialog_content = "ว้าว! ความงามของทุ่งดอกไม้ของนิคินิสไม่มีวันหยุดเติบโต! ฉันจะนำเมล็ดมาบ้างในครั้งหน้า.",
  ui_story_5087_50871601_35_dialog_content = "(ทุ่งดอกไม้เต็มไปด้วยความสวยงามและความอุดมสมบูรณ์จากความช่วยเหลือของชาวนอร์ธแลนด์มากมาย)",
  ui_story_5087_50871601_36_dialog_content = "นิคินิส, ฉันจะช่วยไถดินนะ! โฮ! มันแข็งเป็นหินจริง ๆ นะ.",
  ui_story_5087_50871601_37_dialog_content = "ฉันจะช่วยรดน้ำ!",
  ui_story_5087_50871601_38_dialog_content = "(น้ำจากหิมะที่ละลายจากนอร์ธแลนด์นั้นทำให้ดอกนาร์ซิสซัสที่อ่อนไหวสามารถงอกและเบ่งบานได้)",
  ui_story_5087_50871601_39_dialog_content = "ความฝันนี้... ถึงเวลาตื่นแล้ว",
  ui_story_5087_50871601_40_dialog_content = "ทำไม? คุณลืมตอนจบของเรื่องราวแล้วหรือ?",
  ui_story_5087_50871601_41_dialog_content = "ตอนจบ...",
  ui_story_5087_50871601_42_dialog_content = "\"นับจากวันนั้น เกิดดอกลิลลี่บานออกมาจากดอกนาร์ซิสซัส และทั้งสองก็ครองคู่กันอย่างมีความสุขชั่วกาลนาน\"",
  ui_story_5087_50871601_43_dialog_content = "ทำไมคุณถึงคิดจะทิ้งฉันไว้อีกครั้งหลังจากที่สัญญาจะมีจบที่ดีแบบนั้นกับฉัน?",
  ui_story_5087_50871601_44_dialog_content = "นิคินิส!",
  ui_story_5087_50871601_45_dialog_content = "ไม่, นั่นไม่ใช่! ฉัน—",
  ui_story_5087_50871601_46_dialog_content = "<color=#e8d9bb>นิคินิสกำลังจะป้องกันตัวเองเมื่อเธอตกใจและเงียบสนิททันทีที่เห็น\"พี่สาว\"ของเธอ</color>",
  ui_story_5087_50871601_47_dialog_content = "คุณไม่ใช่พี่สาวฉัน... คุณคือกระจก...",
  ui_story_5087_50871601_48_dialog_content = "เนโปลิสก็ยังแพ้คุณในที่สุด...",
  ui_story_5087_50871601_49_dialog_content = "แพ้? ชนะ? ทั้งหมดนี้เป็นจินตนาการของคุณเอง นิคินิส",
  ui_story_5087_50871601_50_dialog_content = "ฉันเป็นพี่สาวของคุณ และเธอคือฉัน ตัวเลือกเดียวที่คุณมีคือการเชื่อ!",
  ui_story_5087_50871601_51_dialog_content = "ไม่งั้น มันจะไม่ทำให้คุณมีทางเลือกอื่นนอกจากต้องต่อสู้กับฉันรึเปล่า?",
  ui_story_5087_50871601_52_dialog_content = "ฉัน...",
  ui_story_5087_50871601_53_dialog_content = "หยุดฉัน, ทำลายฉัน, ย่ำยีความปรารถนาของฉัน, และทำลายความหวังในการรอดชีวิตของฉัน... คุณจริงๆ แล้วสามารถทำทุกอย่างนั้นได้หรือไม่?",
  ui_story_5087_50871601_54_dialog_content = "คุณไม่สามารถทำได้ใช่ไหม? เพราะคุณคือนิคินิส ดอกนาร์ซิสซัสที่รักดอกลิลลี่...",
  ui_story_5087_50871601_55_dialog_content = "ไม่, ฉัน... คุณไม่ใช่...",
  ui_story_5087_50871601_56_dialog_content = "ตอนนี้ กลับมาอยู่ที่ฝั่งของฉัน ให้ฉันได้เปลี่ยนที่คุณและแสวงหาความเสรี... อ๊าก—",
  ui_story_5087_50871601_57_dialog_content = "อึก... อ๊ากกกก!",
  ui_story_5087_50871601_58_dialog_content = "...นิคินิส...",
  ui_story_5087_50871601_59_dialog_content = "เนโปลิสเหรอ?",
  ui_story_5087_50871601_60_dialog_content = "เนโปลิส นั่นคุณหรือเปล่า? คุณยังอยู่ที่นี่หรือ? คุณจริงๆ ยัง... ไม่ใช่แค่ภาพลวงตาของฉัน. คุณไม่ได้แพ้มัน—",
  ui_story_5087_50871601_61_dialog_content = "... ตอนจบ... ของเรื่องราว...",
  ui_story_5087_50871601_62_dialog_content = "ฉากจบ? ฉันเข้าใจแล้ว ดังนั้นคุณต้องการมีชีวิตอีกครั้งใช่ไหม?",
  ui_story_5087_50871601_63_dialog_content = "แน่นอน มันก็ถูกต้องที่คุณจะต้องมีชีวิตและมายืนแทนฉันในความเป็นจริง—",
  ui_story_5087_50871601_64_dialog_content = "เปล่านะ...",
  ui_story_5087_50871601_65_dialog_content = "?",
  ui_story_5087_50871601_66_dialog_content = "\"แม้ดอกลิลลี่จะกลับมา แต่ความบริสุทธิ์ของเธอก็สูญหายไป ซึ่งเธอกลายเป็นดอกไม้สีดำที่ถูกสีดำจากหิมะที่เสียโทรม\"",
  ui_story_5087_50871601_67_dialog_content = "นั่นคือ... จุดจบที่แท้จริง...",
  ui_story_5087_50871601_68_dialog_content = "เนโปลิส คุณกำลังพูดอะไร—",
  ui_story_5087_50871601_69_dialog_content = "กระจกวิเศษและฉันไม่สามารถแยกจากกันได้แล้ว และฉันไม่ใช่ฉันที่เคยเป็นอีกต่อไป ถึงเวลาแล้ว... สำหรับฉันที่จะไป.",
  ui_story_5087_50871601_70_dialog_content = "แต่มันต่างสำหรับคุณ",
  ui_story_5087_50871601_71_dialog_content = "ฉันไม่อยากฟังอีกคำไหนเลย! เนโปลิส... ทุกอย่างจะเป็นไปด้วยดี...",
  ui_story_5087_50871601_72_dialog_content = "นิคินิส พี่สาวที่ฉันรัก จะไม่นอนลงในหิมะที่มืดมิด",
  ui_story_5087_50871601_73_dialog_content = "เธอจะข้ามหิมะและเอาชนะความทุกข์ที่นำมาโดยชะตากรรม...",
  ui_story_5087_50871601_74_dialog_content = "เธอจะล้ำไปเหนือการป้องกันของพี่สาวเพื่อมาเห็นโลกและรักคนมากขึ้น...",
  ui_story_5087_50871601_75_dialog_content = "เธอจะเติบโตอย่างมีศักดิ์ศรีและแข็งแกร่งเพื่อปกป้องมรดก นิทาน และบทกวีของนอร์ธแลนด์ และเธอจะกระจายพระคุณของดอกไม้ไปยังดินแดนที่ห่างไกล...",
  ui_story_5087_50871601_76_dialog_content = "เธอจะเก็บสิ่งที่ถูกลืม คืนสิ่งที่สูญหาย และเขียนจบบทกวีของเรา เพื่อให้บทสวดใหม่สามารถเกิดขึ้น!",
  ui_story_5087_50871601_77_dialog_content = "งั้น, สู้.",
  ui_story_5087_50871601_78_dialog_content = "!",
  ui_story_5087_50871601_79_dialog_content = "บดขยี้ฉัน ทำลายฉัน และสิ้นสุดฉัน ให้กระจกวิเศษไม่มีอะไรที่จะพึ่งพาอีก!",
  ui_story_5087_50871601_80_dialog_content = "ให้ฉันคืนอนาคตที่คุณคู่ควร ดังนั้นคุณจึงจะบินสูงด้วยปีกของคุณ—",
  ui_story_5087_50871601_81_dialog_content = "ฉันเชื่อในตัวคุณ.",
  ui_story_5087_50871601_82_dialog_content = "เนโปลิส...",
  ui_story_5087_50871601_83_dialog_content = "อัก... อัก... อ้าว!",
  ui_story_5087_50871601_84_dialog_content = "ฮิฮิ... สุดท้ายแล้ว คุณยังคงดื้อรั้นไม่ยอมรับทางเดียวที่จะนำไปสู่ความสุขเหรอ? พี่สาวของฉัน...",
  ui_story_5087_50871601_85_dialog_content = "เนโพลิส! อ้าววว!",
  ui_story_5087_50871602_1_dialog_content = "<color=#e8d9bb>แสงสะท้อนสีเขียวเข้มของออโรราเลียนเลื่อนไปทั่วน้ำของทะเลสาบมิเรอร์เหมือนงูที่กำลังลื่นไถลไปใต้ผิวน้ำ</color>",
  ui_story_5087_50871602_2_dialog_content = "<color=#e8d9bb>เสียงกรีดร้องและเสียงปะทะของการต่อสู้ได้สิ้นสุดลง ใสเหมือนกระจก และยังคงเดิมอยู่เสมอ นั่นคือทะเลสาบกระจกเงาที่ไม่เคยเปลี่ยนแปลง</color>",
  ui_story_5087_50871602_3_dialog_content = "...",
  ui_story_5087_50871602_4_dialog_content = "<color=#e8d9bb>\"ฉันจะอยู่ที่นั่นเมื่อคุณต้องการฉัน...\"</color>",
  ui_story_5087_50871602_5_dialog_content = "<color=#e8d9bb>คำพูดสุดท้ายของเนโปลิสยังคงสะท้อนอยู่ในหูของนิคินิส</color>",
  ui_story_5087_50871602_6_dialog_content = "<color=#e8d9bb>เธอยืนอยู่ที่นั่นอย่างเงียบ ๆ ท่ามกลางกลีบดอกไม้สีขาวบริสุทธิ์ที่ถูกฉีกยับยั้ว</color>",
  ui_story_5087_50871602_7_dialog_content = "<color=#e8d9bb>กลิ่นดอกไม้ชวนเมาเต็มอยู่ทั่วท้องฟ้า.</color>",
  ui_story_5087_50871602_8_dialog_content = "นิคินิส! คุณทำได้แล้ว!",
  ui_story_5087_50871602_9_dialog_content = "ถ้าคุณไม่ได้หยุดกระจกวิเศษทันเวลา PlayerName และฉันคงไม่รอดชีวิตออกมาได้! คุณช่วยชีวิตพวกเรา!",
  ui_story_5087_50871602_10_dialog_content = "... นั่นน่ากลัวมาก! ฉันไม่คิดว่าฉันจะสามารถทนต่อการมองเห็นหิมะอีกครั้ง...",
  ui_story_5087_50871602_11_dialog_content = "อย่าพูดแบบนั้น! คุณจะเบื่อทิวทัศน์ที่เต็มไปด้วยหิมะในนอร์ธแลนด์แน่นอน",
  ui_story_5087_50871602_12_dialog_content = "นิคินิส ขอโทษที่ทำให้เธอต้องเผชิญหน้ากับทุกสิ่งทุกอย่างคนเดียว...",
  ui_story_5087_50871602_13_dialog_content = "ฉันสบายดี, องค์ราชินี และ... PlayerName—",
  ui_story_5087_50871602_14_dialog_content = "ขอบคุณที่ใช้บริการ",
  ui_story_5087_50871602_15_dialog_content = "... ดูเหมือนว่าคุณไม่ต้องการให้โน้มน้าวเพิ่มเติม",
  ui_story_5087_50871602_16_dialog_content = "ฉันจะเจอคุณที่อีกฝั่งนะ!",
  ui_story_5087_50871602_17_dialog_content = "เฮ้! ว-เดี๋ยวนะ! ชาญ่า! คุณกำลังทำอะไร... หวาาา! เราจะกระโดดลงไปหรอ? ฉันต้องการเวลาเพิ่มเติมในการเตรียมตัวสำหรับสิ่งนี้—",
  ui_story_5087_50871602_18_dialog_content = "<color=#e8d9bb>ซ่า! ลูกน้ำกระจายไปทั่วทะเลสาบ แต่ไม่นานก็สงบเงียบอีกครั้ง.</color>",
  ui_story_5087_50871602_19_dialog_content = "<color=#e8d9bb>กลิ่นหอมของดอกไม้ลอยผ่านนิคินิส เธออีกครั้งถูกทิ้งไว้คนเดียวรอบ ๆ ด้วยดอกไม้ในทุ่ง</color>",
  ui_story_5087_50871602_20_dialog_content = "เนโปลิส...",
  ui_story_5087_50871602_21_dialog_content = "ถึงเวลาที่จะออกไปสู่โลกที่คุณต่อสู้เพื่อฉันอย่างหนัก... โลกที่ไม่มีคุณอยู่",
  ui_story_5087_50871602_22_dialog_content = "ฉันต้องมีชีวิตที่ดีแม้ว่าคุณจะไม่อยู่... ใช่ไหม?",
  ui_story_5087_50871602_23_dialog_content = "<color=#e8d9bb>นิคินิสเริ่มเดินเข้าหาทะเลสาบกระจกเงา ถ้าเธอสามารถอยู่ข้างทะเลสาบนี้ได้นานขึ้นเพียงเล็กน้อย แค่เล็กน้อยเท่านั้น</color>",
  ui_story_5087_50871602_24_dialog_content = "<color=#e8d9bb>แต่น่าเสียดาย มันใช้เวลาเพียงไม่กี่ก้าวเท่านั้นในการเดินไปถึงขอบ นิคินิสมองลงไปที่น้ำในทะเลสาบที่ทำให้ชายชุดของเธอเปียก—</color>",
